+    expect(find.textContaining('Thinking'), findsOneWidget);
+
+    const eye = Color(0xFF60D0D0);
+    const mouth = Color(0xFF70A0E0);
+    TextSpan root() => tester
+        .widget<RichText>(
+          find.descendant(
+            of: find.byType(KaomojiFaceText),
