+  void _onTick(Duration elapsed) {
+    if (_lastSwap != null && elapsed - _lastSwap! < kKaomojiSwapPeriod) {
+      return;
+    }
+    _lastSwap = elapsed;
+    setState(() => _face = _picker.next());
+  }
+
+  @override
+  Widget build(BuildContext context) => widget.builder(context, _face);
+}
