+    super.initState();
+    _face = _picker.first();
+    _syncTicker();
+  }
+
+  @override
+  void didUpdateWidget(KaomojiSwapper oldWidget) {
+    super.didUpdateWidget(oldWidget);
+    if (oldWidget.active != widget.active) _syncTicker();
+  }
+
+  @override
+  void dispose() {
+    _ticker.dispose();
+    super.dispose();
+  }
