+        // reaching into flutter_svg's provider internals.
+        key: ValueKey<KaomojiFace>(face),
+        dimension: size,
+        child: SvgPicture.string(kaomojiFaceSvg(face), fit: BoxFit.contain),
+      ),
+    );
+  }
+}
