import 'package:fa_ui/fa_ui.dart';
import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  testWidgets('probe: tree under KaomojiThinkingIcon', (tester) async {
    await tester.pumpWidget(
      MaterialApp(
        home: Scaffold(
          body: Center(
            child: KaomojiThinkingIcon(size: 16, active: false),
          ),
        ),
      ),
    );
    final boxes = tester.widgetList<SizedBox>(
      find.descendant(
        of: find.byType(KaomojiThinkingIcon),
        matching: find.byType(SizedBox),
      ),
    );
    // ignore: avoid_print
    print('MATCHED ${boxes.length} SizedBox widgets:');
    for (final b in boxes) {
      // ignore: avoid_print
      print('  ${b.runtimeType} key=${b.key} w=${b.width} h=${b.height}');
    }
    // Dump the subtree types.
    void walk(Element el, int depth) {
      // ignore: avoid_print
      print('${'  ' * depth}${el.widget.runtimeType}');
      el.visitChildren((c) => walk(c, depth + 1));
    }

    walk(tester.element(find.byType(KaomojiThinkingIcon)), 0);
  });
}

