+/// with a pending timer — and [random] seeds the picks so widget tests
+/// are deterministic.
+class KaomojiSwapper extends StatefulWidget {
+  const KaomojiSwapper({
+    super.key,
+    required this.builder,
+    this.active = true,
+    this.random,
+  });
