        of: find.byType(KaomojiThinkingIcon),
        matching: find.byType(SizedBox),
      ),
    );
    // ignore: avoid_print
    print('MATCHED ${boxes.length} SizedBox widgets:');
    for (final b in boxes) {
      // ignore: avoid_print
      print('  ${b.runtimeType} key=${b.key} w=${b.width} h=${b.height}');
    }
    // Dump the subtree types.
    void walk(Element el, int depth) {
      // ignore: avoid_print
      print('${'  ' * depth}${el.widget.runtimeType}');
      el.visitChildren((c) => walk(c, depth + 1));
    }

    walk(tester.element(find.byType(KaomojiThinkingIcon)), 0);
  });
}
