import 'package:fa_ui/fa_ui.dart';
import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart'
    show MemoryExecutionEnv;
import 'package:flutter_test/flutter_test.dart';

KaomojiFace _faceOf(WidgetTester tester, int index) {
  final icons = tester.widgetList<KaomojiThinkingIcon>(
    find.byType(KaomojiThinkingIcon),
  );
  expect(icons.length, 2);
  final sized = tester.widgetList<SizedBox>(
    find.byWidgetPredicate((w) => w.key is ValueKey<KaomojiFace>),
  );
  return ((sized.toList()[index]).key! as ValueKey<KaomojiFace>).value;
}

void main() {
  testWidgets('PROBE: two thinking tiles with thinkingLive:true — do both animate?',
      (tester) async {
    Widget tree() => FaUiThemeProvider(
          data: const FaUiTheme(),
          child: MaterialApp(
            theme: buildFahTheme(),
            home: Scaffold(
              body: Column(
                children: [
                  ChatMessageTile(
                    message: const FaChatMessage(role: 'thinking', content: 'old'),
                    images: SandboxImageResolver(MemoryExecutionEnv()),
                    thinkingLive: true,
                  ),
                  ChatMessageTile(
                    message: const FaChatMessage(role: 'thinking', content: 'live'),
                    images: SandboxImageResolver(MemoryExecutionEnv()),
                    thinkingLive: true,
                  ),
                ],
              ),
            ),
          ),
        );
    await tester.pumpWidget(tree());
    final f0 = _faceOf(tester, 0);
    final f1 = _faceOf(tester, 1);
    await tester.pump(const Duration(milliseconds: 950));
    final f0b = _faceOf(tester, 0);
    final f1b = _faceOf(tester, 1);
    // ignore: avoid_print
    print('TILE0 ${f0.text} -> ${f0b.text} changed=${!identical(f0, f0b)}');
    // ignore: avoid_print
    print('TILE1 ${f1.text} -> ${f1b.text} changed=${!identical(f1, f1b)}');
  });
}

