            theme: buildFahTheme(),
            home: Scaffold(
              body: Column(
                children: [
                  ChatMessageTile(
                    message: const FaChatMessage(role: 'thinking', content: 'old'),
                    images: SandboxImageResolver(MemoryExecutionEnv()),
                    thinkingLive: true,
                  ),
                  ChatMessageTile(
                    message: const FaChatMessage(role: 'thinking', content: 'live'),
                    images: SandboxImageResolver(MemoryExecutionEnv()),
                    thinkingLive: true,
                  ),
                ],
              ),
            ),
          ),
        );
    await tester.pumpWidget(tree());
    final f0 = _faceOf(tester, 0);
    final f1 = _faceOf(tester, 1);
