    // ignore: avoid_print
    print('TILE0 ${f0.text} -> ${f0b.text} changed=${!identical(f0, f0b)}');
    // ignore: avoid_print
    print('TILE1 ${f1.text} -> ${f1b.text} changed=${!identical(f1, f1b)}');
